import pandas as pd

def spending_by_user(sales: pd.DataFrame, product: pd.DataFrame) -> pd.DataFrame:
    merged = sales.merge(product, on='product_id', how='inner')
    merged['spending'] = merged['quantity'] * merged['price']
    result = merged.groupby('user_id', as_index=False)['spending'].sum()
    return result.sort_values(['spending', 'user_id'], ascending=[False, True])

