#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<pair<int,long long>> spendingByUser(
            vector<array<int,4>>& sales, vector<pair<int,int>>& product) {
        unordered_map<int,int> price;
        for (auto& p : product) price[p.first] = p.second;
        map<int,long long> spend;
        for (auto& s : sales)
            spend[s[2]] += (long long)s[3] * price[s[1]];
        vector<pair<int,long long>> res(spend.begin(), spend.end());
        sort(res.begin(), res.end(), [](auto& a, auto& b){
            if (a.second != b.second) return a.second > b.second;
            return a.first < b.first;
        });
        return res;
    }
};

