import java.util.*;

class Solution {
    public List<long[]> spendingByUser(int[][] sales, int[][] product) {
        Map<Integer, Integer> price = new HashMap<>();
        for (int[] p : product) price.put(p[0], p[1]);
        Map<Integer, Long> spend = new HashMap<>();
        for (int[] s : sales)
            spend.merge(s[2], (long) s[3] * price.get(s[1]), Long::sum);
        List<long[]> res = new ArrayList<>();
        for (var e : spend.entrySet())
            res.add(new long[]{e.getKey(), e.getValue()});
        res.sort((a, b) -> b[1] != a[1]
                ? Long.compare(b[1], a[1]) : Long.compare(a[0], b[0]));
        return res;
    }
}

