var spendingByUser = function(sales, product) {
    const price = new Map(product.map(p => [p.product_id, p.price]));
    const spend = new Map();
    for (const s of sales)
        spend.set(s.user_id, (spend.get(s.user_id) || 0) + s.quantity * price.get(s.product_id));
    return [...spend.entries()]
        .map(([user_id, spending]) => ({ user_id, spending }))
        .sort((a, b) => b.spending - a.spending || a.user_id - b.user_id);
};
